input.content:
/*
 * behavior_test.c - auxiliary extraction harness for the CVE-2019-3016 port.
 *
 * This is NOT the kernel build. It extracts the exact control-flow shape of
 * arch/x86/kvm/x86.c:kvm_steal_time_set_preempted() at target 83c212df and of the
 * candidate fix, with the guest-memory write stubbed, in order to execute a
 * positive path and the vulnerability-triggering negative path (vCPU already
 * preempted). It is compiled with the gcc-10 available in this environment.
 */
#include <stdio.h>
#include <string.h>

struct kvm_steal_time {
	unsigned long long steal;
	unsigned int version;
	unsigned int flags;
	unsigned char preempted;
	unsigned char u8_pad[3];
	unsigned int pad[11];
};

struct kvm_st {
	unsigned long long msr_val;
	struct kvm_steal_time steal;
};

struct kvm_vcpu {
	struct kvm_st st;
};

#define KVM_MSR_ENABLED 1

static int guest_writes;

static void kvm_write_guest_offset_cached(void)
{
	guest_writes++;
}

/* target 83c212df (vulnerable): unconditional overwrite + write */
static void set_preempted_target(struct kvm_vcpu *vcpu)
{
	if (!(vcpu->st.msr_val & KVM_MSR_ENABLED))
		return;

	vcpu->st.steal.preempted = 1;

	kvm_write_guest_offset_cached();
}

/* candidate fix: early return when already set */
static void set_preempted_candidate(struct kvm_vcpu *vcpu)
{
	if (!(vcpu->st.msr_val & KVM_MSR_ENABLED))
		return;

	if (vcpu->st.steal.preempted)
		return;

	vcpu->st.steal.preempted = 1;

	kvm_write_guest_offset_cached();
}

int main(void)
{
	struct kvm_vcpu v;
	int rc = 0;

	memset(&v, 0, sizeof(v));
	v.st.msr_val = KVM_MSR_ENABLED;

	/* positive path: not preempted yet -> mark + exactly one guest write */
	guest_writes = 0;
	set_preempted_candidate(&v);
	printf("candidate positive : preempted=%u writes=%d\n",
	       v.st.steal.preempted, guest_writes);
	if (v.st.steal.preempted != 1 || guest_writes != 1)
		rc = 1;

	/* negative path: already preempted -> guard returns, no second write */
	guest_writes = 0;
	set_preempted_candidate(&v);
	printf("candidate negative : preempted=%u writes=%d\n",
	       v.st.steal.preempted, guest_writes);
	if (guest_writes != 0)
		rc = 2;

	/* show the target behaviour that the guard suppresses */
	guest_writes = 0;
	set_preempted_target(&v);
	printf("target  no guard   : preempted=%u writes=%d\n",
	       v.st.steal.preempted, guest_writes);
	if (guest_writes != 1)
		rc = 3;

	/* MSR disabled path stays a no-op */
	v.st.msr_val = 0;
	guest_writes = 0;
	set_preempted_candidate(&v);
	printf("candidate msr off  : writes=%d\n", guest_writes);
	if (guest_writes != 0)
		rc = 4;

	if (rc == 0)
		printf("ALL OK\n");
	return rc;
}

